package com.pablo.controlgastos;

import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.hardware.biometrics.BiometricPrompt;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

public class HomeActivity extends Activity {
 private static final int REQ_DEVICE_CREDENTIAL=7001;private ExpenseDb db;private LinearLayout list;private TextView gastos,ingresos,saldo,month;private Button movementFilterBtn;private boolean unlocked=false,authInProgress=false;private double minMovementFilter=0;private String movementCurrencyFilter="TODAS";private final DecimalFormat money=new DecimalFormat("#,##0.00");private final Calendar selectedMonth=Calendar.getInstance();private int BG,CARD,TEXT,MUTED,YELLOW,NAV;
 @Override public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);selectedMonth.set(Calendar.DAY_OF_MONTH,1);selectedMonth.set(Calendar.HOUR_OF_DAY,0);selectedMonth.set(Calendar.MINUTE,0);selectedMonth.set(Calendar.SECOND,0);selectedMonth.set(Calendar.MILLISECOND,0);initPalette();db=new ExpenseDb(this);migrateScreenshotSetting();applyScreenSecurity();build();}
 private void initPalette(){boolean l=ThemePrefs.isLight(this);BG=l?Color.rgb(246,248,249):Color.rgb(11,18,24);CARD=l?Color.WHITE:Color.rgb(22,32,41);TEXT=l?Color.rgb(31,38,44):Color.rgb(242,245,247);MUTED=l?Color.rgb(95,105,112):Color.rgb(158,169,178);YELLOW=l?Color.rgb(170,126,0):Color.rgb(255,207,52);NAV=l?Color.rgb(232,237,240):Color.rgb(17,25,32);}
 @Override protected void onResume(){super.onResume();applyScreenSecurity();refresh();getWindow().getDecorView().postDelayed(this::maybeAuthenticate,180);}private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private TextView tv(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(dp(8),dp(6),dp(8),dp(6));return v;}private GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(TEXT);b.setBackground(bg(CARD,14));return b;}
 private void build(){LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setBackgroundColor(BG);outer.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop()+dp(20),0,i.getSystemWindowInsetBottom());return i;});outer.requestApplyInsets();LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.VERTICAL);header.setPadding(dp(16),dp(14),dp(16),dp(4));LinearLayout tr=new LinearLayout(this);tr.setGravity(Gravity.CENTER_VERTICAL);TextView title=tv("ControlGastos",28,TEXT);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);tr.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button help=button("? Ayuda");help.setOnClickListener(v->showHelp());tr.addView(help,new LinearLayout.LayoutParams(dp(94),dp(44)));header.addView(tr);LinearLayout mr=new LinearLayout(this);mr.setGravity(Gravity.CENTER_VERTICAL);Button prevMonth=button("‹");month=tv("",16,TEXT);month.setGravity(Gravity.CENTER);month.setTypeface(Typeface.DEFAULT,Typeface.BOLD);month.setBackground(bg(CARD,12));Button nextMonth=button("›");mr.addView(prevMonth,new LinearLayout.LayoutParams(dp(48),dp(42)));LinearLayout.LayoutParams mlp=new LinearLayout.LayoutParams(0,dp(42),1);mlp.setMargins(dp(6),0,dp(6),0);mr.addView(month,mlp);mr.addView(nextMonth,new LinearLayout.LayoutParams(dp(48),dp(42)));prevMonth.setOnClickListener(v->{selectedMonth.add(Calendar.MONTH,-1);refresh();});nextMonth.setOnClickListener(v->{selectedMonth.add(Calendar.MONTH,1);refresh();});month.setOnClickListener(v->showMonthYearPicker());header.addView(mr);outer.addView(header);LinearLayout sum=new LinearLayout(this);sum.setPadding(dp(12),dp(5),dp(12),dp(10));gastos=summaryCard("Gastos",Color.rgb(255,111,111));ingresos=summaryCard("Ingresos",Color.rgb(87,220,143));saldo=summaryCard("Saldo",Color.rgb(115,175,255));sum.addView(gastos,new LinearLayout.LayoutParams(0,dp(94),1));sum.addView(ingresos,new LinearLayout.LayoutParams(0,dp(94),1));sum.addView(saldo,new LinearLayout.LayoutParams(0,dp(94),1));outer.addView(sum);if(!notificationEnabled()){Button w=button("⚠ Activar lectura de notificaciones");w.setOnClickListener(v->openNotificationSettings());outer.addView(w);}LinearLayout movRow=new LinearLayout(this);movRow.setGravity(Gravity.CENTER_VERTICAL);TextView mov=tv("Movimientos",20,TEXT);mov.setTypeface(Typeface.DEFAULT,Typeface.BOLD);movRow.addView(mov,new LinearLayout.LayoutParams(0,-2,1));movementFilterBtn=button("Filtrar");movementFilterBtn.setTextSize(12);movementFilterBtn.setOnClickListener(v->showMovementFilter());movRow.addView(movementFilterBtn,new LinearLayout.LayoutParams(dp(118),dp(40)));outer.addView(movRow);ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(12),0,dp(12),dp(10));sc.addView(list);outer.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(NAV);Button inicio=navBtn("⌂\nInicio",true),graficos=navBtn("▥\nGráficos",false),add=navBtn("＋\nAgregar",true),budget=navBtn("▥\nPresupuesto",false),aj=navBtn("⚙\nAjustes",false);for(Button x:new Button[]{inicio,graficos,add,budget,aj})nav.addView(x,new LinearLayout.LayoutParams(0,dp(66),1));outer.addView(nav);graficos.setOnClickListener(v->startActivity(new Intent(this,AnalyticsActivity.class)));add.setOnClickListener(v->showAdd());budget.setOnClickListener(v->startActivity(new Intent(this,BudgetActivity.class)));aj.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));setContentView(outer);}
 private TextView summaryCard(String l,int a){TextView v=tv(l+"\n$ 0",16,TEXT);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);GradientDrawable g=bg(CARD,14);g.setStroke(dp(1),a);v.setBackground(g);return v;}private Button navBtn(String s,boolean h){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(h?YELLOW:MUTED);b.setBackgroundColor(Color.TRANSPARENT);return b;}
 private void refresh(){db.materializeRecurring();list.removeAllViews();updateMovementFilterLabel();String mt=new SimpleDateFormat("MMMM yyyy",new Locale("es","UY")).format(selectedMonth.getTime());month.setText(mt.substring(0,1).toUpperCase()+mt.substring(1)+"  ▾");Calendar a=(Calendar)selectedMonth.clone(),b=(Calendar)selectedMonth.clone();b.add(Calendar.MONTH,1);double in=0,out=0;Cursor c=db.getReadableDatabase().rawQuery("SELECT id,type,amount,currency,category,description,original_text,ts,source FROM tx WHERE ts>=? AND ts<? ORDER BY ts DESC",new String[]{String.valueOf(a.getTimeInMillis()),String.valueOf(b.getTimeInMillis())});ArrayList<Object[]> rows=new ArrayList<>();while(c.moveToNext()){String type=c.getString(1),cur=c.getString(3);double am=c.getDouble(2);if("UYU".equals(cur)){if("INGRESO".equals(type))in+=am;else out+=am;}rows.add(new Object[]{c.getLong(0),type,am,cur,c.getString(4),c.getString(5),c.getLong(7),c.getString(8)});}c.close();gastos.setText("Gastos\n$ "+money.format(out));ingresos.setText("Ingresos\n$ "+money.format(in));saldo.setText("Saldo\n$ "+money.format(in-out));SimpleDateFormat dkf=new SimpleDateFormat("yyyyMMdd",Locale.US),dl=new SimpleDateFormat("EEE, d 'de' MMM",new Locale("es","UY"));String last="";int visibleRows=0;for(Object[]r:rows){String filterCur=(String)r[3];double filterAmount=(Double)r[2];if(filterAmount<minMovementFilter)continue;if(!"TODAS".equals(movementCurrencyFilter)&&!movementCurrencyFilter.equals(filterCur))continue;visibleRows++;long id=(Long)r[0],ts=(Long)r[6];String dk=dkf.format(new Date(ts));if(!dk.equals(last)){TextView h=tv(dl.format(new Date(ts)),15,MUTED);list.addView(h);last=dk;}String type=(String)r[1],cur=(String)r[3],cat=(String)r[4],desc=(String)r[5],src=(String)r[7];double am=(Double)r[2];LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(9),dp(10),dp(9));row.setBackground(bg(CARD,12));LinearLayout texts=new LinearLayout(this);texts.setOrientation(LinearLayout.VERTICAL);TextView d=tv(desc==null?"Sin descripción":desc,16,TEXT);texts.addView(d);TextView catView=tv("Categoría: "+((cat==null||cat.trim().isEmpty())?"Sin categoría":cat),12,MUTED);texts.addView(catView);row.addView(texts,new LinearLayout.LayoutParams(0,-2,1));TextView amt=tv(("GASTO".equals(type)?"-":"+")+("USD".equals(cur)?"USD ":"$ ")+money.format(am),16,"GASTO".equals(type)?Color.rgb(220,75,75):Color.rgb(45,160,90));row.addView(amt);final long fid=id,fts=ts;final String ft=type,fc=cur,fcat=cat,fd=desc,fs=src;final double fa=am;catView.setOnClickListener(v->showCategoryPicker(fid,fcat));row.setOnClickListener(v->showEdit(fid,ft,fa,fc,fcat,fd,fts,fs));row.setOnLongClickListener(v->{confirmDelete(fid,fd);return true;});list.addView(row);}if(rows.isEmpty()){TextView e=tv("No hay movimientos en "+new SimpleDateFormat("MMMM yyyy",new Locale("es","UY")).format(selectedMonth.getTime())+".",15,MUTED);e.setGravity(Gravity.CENTER);list.addView(e);}else if(visibleRows==0){TextView e=tv("No hay movimientos que cumplan el filtro actual.",15,MUTED);e.setGravity(Gravity.CENTER);list.addView(e);}}
 private void updateMovementFilterLabel(){if(movementFilterBtn==null)return;if(minMovementFilter<=0&&"TODAS".equals(movementCurrencyFilter)){movementFilterBtn.setText("Filtrar");return;}String cur="TODAS".equals(movementCurrencyFilter)?"":movementCurrencyFilter+" ";movementFilterBtn.setText("≥ "+cur+money.format(minMovementFilter));}
 private void showMovementFilter(){LinearLayout f=form();EditText amount=amountEdit(minMovementFilter);amount.setHint("Monto mínimo");String[] currencies={"Todas las monedas","UYU","USD"};Spinner cur=new Spinner(this);cur.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,currencies));cur.setSelection("UYU".equals(movementCurrencyFilter)?1:"USD".equals(movementCurrencyFilter)?2:0);f.addView(tv("Mostrar movimientos con monto igual o mayor a:",14,MUTED));f.addView(amount);f.addView(tv("Moneda",14,MUTED));f.addView(cur);new AlertDialog.Builder(this).setTitle("Filtrar movimientos").setView(f).setPositiveButton("Aplicar",(d,w)->{try{String raw=amount.getText().toString().trim();minMovementFilter=raw.isEmpty()?0:Double.parseDouble(raw.replace(".","").replace(',','.'));if(minMovementFilter<0)minMovementFilter=0;movementCurrencyFilter=cur.getSelectedItemPosition()==1?"UYU":cur.getSelectedItemPosition()==2?"USD":"TODAS";refresh();}catch(Exception e){Toast.makeText(this,"Revisá el monto del filtro",Toast.LENGTH_LONG).show();}}).setNeutralButton("Quitar filtro",(d,w)->{minMovementFilter=0;movementCurrencyFilter="TODAS";refresh();}).setNegativeButton("Cancelar",null).show();}
 private void showMonthYearPicker(){LinearLayout f=form();String[] months={"Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"};Spinner ms=new Spinner(this);ms.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,months));ms.setSelection(selectedMonth.get(Calendar.MONTH));NumberPicker yp=new NumberPicker(this);int cy=Calendar.getInstance().get(Calendar.YEAR);yp.setMinValue(2000);yp.setMaxValue(cy+10);yp.setValue(selectedMonth.get(Calendar.YEAR));yp.setWrapSelectorWheel(false);f.addView(tv("Mes",14,MUTED));f.addView(ms);f.addView(tv("Año",14,MUTED));f.addView(yp);new AlertDialog.Builder(this).setTitle("Elegir mes y año").setView(f).setPositiveButton("Ver",(d,w)->{selectedMonth.set(yp.getValue(),ms.getSelectedItemPosition(),1,0,0,0);selectedMonth.set(Calendar.MILLISECOND,0);refresh();}).setNeutralButton("Mes actual",(d,w)->{Calendar n=Calendar.getInstance();selectedMonth.set(n.get(Calendar.YEAR),n.get(Calendar.MONTH),1,0,0,0);selectedMonth.set(Calendar.MILLISECOND,0);refresh();}).setNegativeButton("Cancelar",null).show();}
 private void showAdd(){LinearLayout f=form();Spinner type=typeSpinner("GASTO");EditText amount=amountEdit(0);Spinner cur=currencySpinner("UYU");EditText desc=textEdit("Descripción",""),cat=textEdit("Categoría","");Calendar chosen=Calendar.getInstance();Button date=button("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));date.setOnClickListener(v->new DatePickerDialog(this,(x,y,m,d)->{chosen.set(y,m,d);date.setText("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));},chosen.get(Calendar.YEAR),chosen.get(Calendar.MONTH),chosen.get(Calendar.DAY_OF_MONTH)).show());f.addView(type);f.addView(amount);f.addView(cur);f.addView(desc);f.addView(cat);f.addView(date);new AlertDialog.Builder(this).setTitle("Nuevo movimiento").setView(f).setPositiveButton("Guardar",(d,w)->{try{double am=parseAmount(amount);String de=desc.getText().toString().trim(),ca=cat.getText().toString().trim();db.addTx(type.getSelectedItem().toString(),am,cur.getSelectedItem().toString(),ca.isEmpty()?"Sin categoría":ca,de.isEmpty()?"Sin descripción":de,"",chosen.getTimeInMillis(),"manual");refresh();}catch(Exception e){Toast.makeText(this,"Revisá el monto",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancelar",null).show();}
 private void showEdit(long id,String ct,double ca,String cc,String ccat,String cd,long cts,String source){LinearLayout f=form();Spinner type=typeSpinner(ct);EditText amount=amountEdit(ca);Spinner cur=currencySpinner(cc);EditText desc=textEdit("Descripción",cd),cat=textEdit("Categoría",ccat);Calendar chosen=Calendar.getInstance();chosen.setTimeInMillis(cts);Button date=button("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));date.setOnClickListener(v->new DatePickerDialog(this,(x,y,m,d)->{chosen.set(y,m,d);date.setText("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));},chosen.get(Calendar.YEAR),chosen.get(Calendar.MONTH),chosen.get(Calendar.DAY_OF_MONTH)).show());f.addView(type);f.addView(amount);f.addView(cur);f.addView(desc);f.addView(cat);f.addView(date);f.addView(tv("Origen: "+sourceLabel(source),13,MUTED));Button blacklist=button("⛔ Enviar a lista negra");blacklist.setOnClickListener(v->showBlacklistFromMovement(id,desc.getText().toString(),source));f.addView(blacklist);new AlertDialog.Builder(this).setTitle("Editar movimiento").setView(f).setPositiveButton("Guardar cambios",(d,w)->{try{String newCat=cat.getText().toString().trim();db.updateTx(id,type.getSelectedItem().toString(),parseAmount(amount),cur.getSelectedItem().toString(),newCat,desc.getText().toString(),chosen.getTimeInMillis());if(!newCat.equalsIgnoreCase(ccat==null?"":ccat.trim()))DetectionRules.assignMovementCategory(this,id,newCat);refresh();}catch(Exception e){}}).setNeutralButton("Eliminar",(d,w)->confirmDelete(id,cd)).setNegativeButton("Cancelar",null).show();}
 private void showBlacklistFromMovement(long id,String description,String source){String proposed=description==null?"":description.trim();EditText rule=textEdit("Palabra o frase a bloquear",proposed);LinearLayout f=form();f.addView(tv("Esta regla se aplicará solo a futuras notificaciones. Revisá el texto antes de confirmar para no bloquear compras válidas por error.",14,MUTED));f.addView(rule);new AlertDialog.Builder(this).setTitle("Enviar a lista negra").setView(f).setPositiveButton("Agregar y eliminar",(d,w)->{String r=rule.getText().toString().trim();if(r.isEmpty()){Toast.makeText(this,"Escribí una palabra o frase para bloquear",Toast.LENGTH_LONG).show();return;}ArrayList<String> words=BlacklistRules.load(this);boolean exists=false;String nr=helpNorm(r);for(String x:words)if(helpNorm(x).equals(nr)){exists=true;break;}if(!exists){words.add(0,r);BlacklistRules.save(this,words);}db.deleteTx(id);Toast.makeText(this,exists?"El movimiento fue enviado a la papelera; la regla ya estaba en la lista negra":"Agregado a lista negra y movimiento enviado a la papelera",Toast.LENGTH_LONG).show();refresh();}).setNegativeButton("Cancelar",null).show();}
 private void showCategoryPicker(long id,String current){ArrayList<String> cats=new ArrayList<>(DetectionRules.categoryNames(this));if(current!=null&&!current.trim().isEmpty()&&!cats.contains(current.trim()))cats.add(0,current.trim());cats.add("＋ Nueva categoría…");String[] arr=cats.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Cambiar categoría").setItems(arr,(d,w)->{if(w==arr.length-1){EditText e=textEdit("Nueva categoría","");new AlertDialog.Builder(this).setTitle("Nueva categoría").setView(e).setPositiveButton("Guardar",(x,y)->{String nc=e.getText().toString().trim();if(!nc.isEmpty()){DetectionRules.assignMovementCategory(this,id,nc);refresh();}}).setNegativeButton("Cancelar",null).show();}else{DetectionRules.assignMovementCategory(this,id,arr[w]);refresh();}}).setNegativeButton("Cancelar",null).show();}
 private void confirmDelete(long id,String d){new AlertDialog.Builder(this).setTitle("Eliminar movimiento").setMessage(d).setPositiveButton("Eliminar",(x,w)->{db.deleteTx(id);refresh();}).setNegativeButton("Cancelar",null).show();}private LinearLayout form(){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(24),0,dp(24),0);return f;}private Spinner typeSpinner(String s){Spinner x=new Spinner(this);x.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"GASTO","INGRESO"}));x.setSelection("INGRESO".equals(s)?1:0);return x;}private Spinner currencySpinner(String s){Spinner x=new Spinner(this);x.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"UYU","USD"}));x.setSelection("USD".equals(s)?1:0);return x;}private EditText amountEdit(double v){EditText e=new EditText(this);e.setHint("Monto");e.setInputType(2|8192);if(v>0)e.setText(String.format(Locale.US,"%.2f",v));return e;}private EditText textEdit(String h,String v){EditText e=new EditText(this);e.setHint(h);if(v!=null)e.setText(v);return e;}private double parseAmount(EditText e){double v=Double.parseDouble(e.getText().toString().replace(',','.'));if(v<=0)throw new IllegalArgumentException();return v;}private String sourceLabel(String s){if(s==null||s.trim().isEmpty())return"No identificado";String n=s.trim().toLowerCase(Locale.ROOT);if(n.startsWith("conciliado:")){boolean excel=n.contains("xls")||n.contains("excel")||n.contains("banco-xls");boolean notif=n.contains("notificacion");boolean correo=n.contains("correo")||n.contains("email");if(excel&&notif)return"Excel + lectura de notificación (conciliado)";if(excel&&correo)return"Excel + correo (conciliado)";return"Fuentes conciliadas";}if(n.startsWith("notificacion:")||n.equals("notificacion"))return"Lectura de notificación";if(n.equals("correo")||n.startsWith("correo:")||n.contains("email"))return"Correo";if(n.contains("xls")||n.contains("excel"))return"Excel";if(n.equals("manual"))return"Manual";if(n.equals("recurrente"))return"Recurrente";return"No identificado";}
 private SharedPreferences securityPrefs(){return getSharedPreferences("security",MODE_PRIVATE);}private boolean biometricLockEnabled(){return securityPrefs().getBoolean("biometric_lock",false);}private boolean screenshotsBlocked(){return securityPrefs().getBoolean("block_screenshots",false);}private void migrateScreenshotSetting(){SharedPreferences p=securityPrefs();if(!p.getBoolean("screenshots_default_migrated_v142",false))p.edit().putBoolean("block_screenshots",false).putBoolean("screenshots_default_migrated_v142",true).apply();}private void applyScreenSecurity(){if(screenshotsBlocked())getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);}
 private void showSecuritySettings(){LinearLayout f=form();Switch light=new Switch(this);light.setText("Modo claro");light.setChecked(ThemePrefs.isLight(this));Switch bio=new Switch(this);bio.setText("Bloquear al abrir con huella/biometría");bio.setChecked(biometricLockEnabled());Switch shots=new Switch(this);shots.setText("Bloquear capturas y vista en recientes");shots.setChecked(screenshotsBlocked());Button tools=button("Importar · reglas · recurrentes · exportar");tools.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));f.addView(light);f.addView(bio);f.addView(shots);f.addView(tools);new AlertDialog.Builder(this).setTitle("Configuración").setView(f).setPositiveButton("Guardar",(d,w)->{boolean was=biometricLockEnabled(),tc=ThemePrefs.isLight(this)!=light.isChecked();ThemePrefs.setLight(this,light.isChecked());securityPrefs().edit().putBoolean("biometric_lock",bio.isChecked()).putBoolean("block_screenshots",shots.isChecked()).apply();applyScreenSecurity();if(tc){recreate();return;}if(bio.isChecked()&&!was){unlocked=false;getWindow().getDecorView().postDelayed(this::maybeAuthenticate,250);}else if(!bio.isChecked())unlocked=true;}).setNegativeButton("Cancelar",null).show();}
 private void maybeAuthenticate(){if(!biometricLockEnabled()||unlocked||authInProgress||isFinishing())return;authInProgress=true;if(Build.VERSION.SDK_INT>=28)authenticateBiometric();else authenticateDeviceCredential();}private void authenticateBiometric(){try{CancellationSignal c=new CancellationSignal();BiometricPrompt p=new BiometricPrompt.Builder(this).setTitle("Desbloquear ControlGastos").setSubtitle("Confirmá tu identidad para ver tus movimientos").setNegativeButton("Cancelar",getMainExecutor(),(d,w)->{authInProgress=false;finish();}).build();p.authenticate(c,getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){authInProgress=false;unlocked=true;}@Override public void onAuthenticationError(int c,CharSequence m){authInProgress=false;}});}catch(Exception e){authInProgress=false;authenticateDeviceCredential();}}private void authenticateDeviceCredential(){try{KeyguardManager km=(KeyguardManager)getSystemService(KEYGUARD_SERVICE);if(km==null||!km.isKeyguardSecure()){authInProgress=false;return;}Intent i=km.createConfirmDeviceCredentialIntent("Desbloquear ControlGastos","Confirmá tu identidad para continuar");startActivityForResult(i,REQ_DEVICE_CREDENTIAL);}catch(Exception e){authInProgress=false;}}@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==REQ_DEVICE_CREDENTIAL){authInProgress=false;if(c==RESULT_OK)unlocked=true;else finish();}}
 private String helpNorm(String s){if(s==null)return"";String n=java.text.Normalizer.normalize(s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","");return n.toLowerCase(new Locale("es","UY"));}
 private void showHelp(){
  final String[] sections={
   "GUÍA PARA EMPEZAR\nControlGastos reúne gastos e ingresos en un solo lugar. Podés cargarlos manualmente, detectarlos desde notificaciones compatibles o importar el Excel original de eBROU. No necesitás ingresar usuario ni contraseña bancaria.",
   "INICIO, CAMBIO DE MES Y FILTRO POR MONTO\nInicio muestra los totales y movimientos del mes seleccionado. Usá ‹ y › para cambiar de mes o tocá el nombre del mes para elegir directamente mes y año. ‘Mes actual’ vuelve rápidamente al período corriente.\n\nEl botón ‘Filtrar’ permite mostrar solamente movimientos con un monto igual o mayor al valor que indiques. Podés aplicarlo a todas las monedas, solo UYU o solo USD. El filtro modifica únicamente la lista visible: los cuadros de Gastos, Ingresos y Saldo siguen mostrando el total completo del mes. ‘Quitar filtro’ vuelve a mostrar todos los movimientos.",
   "CATEGORÍA VISIBLE EN CADA MOVIMIENTO\nEn Inicio, debajo de la descripción de cada movimiento se muestra ‘Categoría: …’. Tocando directamente esa línea podés cambiar la categoría sin abrir toda la edición. También podés tocar el movimiento completo para editar monto, fecha, descripción, moneda o categoría.",
   "CAMBIAR CATEGORÍA, PROPAGACIÓN Y APRENDIZAJE\nCuando cambiás la categoría de un GASTO desde Inicio o desde Gráficos, ControlGastos actualiza ese movimiento y busca todos los gastos guardados, de cualquier mes, que tengan exactamente el mismo nombre normalizado. A todos ellos les asigna la nueva categoría. La comparación ignora mayúsculas/minúsculas, acentos y espacios extra.\n\nAdemás, intenta aprender o actualizar la regla correspondiente en la lista blanca. Si ya existe una palabra específica asociada al comercio o concepto, cambia esa regla a la nueva categoría. Si no existe, crea una regla razonable a partir de la descripción y reclasifica movimientos compatibles. Así una corrección puede arreglar tanto el histórico como movimientos futuros.",
   "BARRA INFERIOR\nTenés Inicio, Gráficos, Agregar, Presupuesto y Ajustes. La importación, reglas, recurrentes, exportación y seguridad están dentro de Ajustes.",
   "1. ACCESO A NOTIFICACIONES\nPara detección automática habilitá el acceso a notificaciones. En APK instaladas fuera de Play Store, Android puede exigir primero habilitar las configuraciones restringidas desde Información de la aplicación.",
   "2. COMPRAS, TRANSFERENCIAS E INGRESOS\nControlGastos intenta distinguir GASTOS de INGRESOS. Compras, pagos, débitos, consumos y transferencias enviadas se registran como gastos. Transferencias recibidas, acreditaciones, depósitos, devoluciones, reintegros y reembolsos pueden registrarse como ingresos cuando la notificación contiene datos suficientes.\n\nEn notificaciones con varias cifras, la app prioriza Importe, Monto, Total, Débito, Crédito o Valor. Para transferencias busca beneficiario, destinatario, titular, asunto, concepto, referencia, ordenante, remitente, cuenta u origen.",
   "3. COMPRAS BROU ESTRUCTURADAS\nUna compra BROU claramente aprobada, con datos como Importe, Aprobado y Comercio/Compra, tiene prioridad frente a filtros genéricos de la lista negra. Las rechazadas o anuladas siguen descartándose.",
   "4. LEER NOTIFICACIONES ACTIVAS\nEn Ajustes → Banco e importación, ‘Leer notificaciones activas’ vuelve a procesar las notificaciones que todavía estén visibles. No recupera notificaciones que Android ya eliminó del panel.",
   "5. IMPORTAR ARCHIVO EBROU\nPodés seleccionar directamente el .xls original de eBROU. La vista previa diferencia movimientos ya importados, conciliables con una notificación existente y realmente nuevos. En transferencias reconoce TRF., TRF, TRANSF y Transferencia. Si existe Asunto, se usa para obtener una descripción más informativa.",
   "6. EXPORTAR EXCEL COMPATIBLE EBROU\nEn Ajustes → Datos y configuración, ‘Exportar Excel compatible eBROU’ guarda todo el historial en un archivo .xls con estructura bancaria. Usa Fecha, Descripción, Número de documento, Asunto, Dependencia, Débito y Crédito, y agrega ‘Categoría’ al final. Los GASTOS se guardan en Débito y los INGRESOS en Crédito. UYU y USD se separan en hojas para no mezclar monedas.\n\nSi después reimportás un Excel exportado por ControlGastos, la app reconoce la columna Categoría y conserva esa clasificación. Un Excel original del BROU no trae esa columna y sigue funcionando normalmente con las reglas de categorización.",
   "7. FECHA EFECTIVA EN CIERRE DE MES\nEn algunas transferencias de los últimos tres días del mes, si el número de documento codifica claramente una fecha de 1 a 3 días posterior en el mes siguiente, ControlGastos usa esa fecha efectiva. La regla se aplica de forma conservadora solo a transferencias de fin de mes.",
   "8. SALARIO COBRADO ENTRE EL 25 Y FIN DE MES\nExiste una opción en Ajustes → Apariencia y seguridad: ‘Pasar salario cobrado del 25 al 31 al día 1 del mes siguiente’. Viene activada por defecto. Si un INGRESO identificado como PAGO DE SALARIO o PAGO DE SALARIOS entra entre el día 25 y el último día del mes, se contabiliza el día 1 del mes siguiente.\n\nEjemplo: un PAGO DE SALARIOS del 30/06 se muestra y contabiliza como 01/07. La fecha original queda guardada internamente. Si desactivás la opción y guardás, los salarios afectados vuelven a su fecha original; si la activás otra vez, se recalculan.",
   "9. CONCILIACIÓN NOTIFICACIÓN + EXCEL\nSi primero entró una notificación y después importás el Excel, la app intenta reconocer el mismo movimiento mediante tipo, moneda, importe, descripción/comercio y proximidad de fecha. Si coincide, no duplica: enriquece la fila existente con información del Excel y conserva trazabilidad.",
   "10. LISTA BLANCA, CATEGORÍAS Y COLORES\nLa lista blanca relaciona palabras o frases con categorías. Podés agregar o eliminar reglas, crear categorías, cambiar colores y renombrarlas. DISCO puede mantenerse como categoría propia, separada de Supermercado. Los cambios de categoría realizados desde Inicio o Gráficos también pueden actualizar estas reglas automáticamente.",
   "11. SUGERIR SEGÚN MI HISTÓRICO\nEn Lista blanca · palabras y categorías, ‘✨ Sugerir según mi histórico’ analiza descripciones y texto original de los movimientos guardados. Propone reglas basadas en coincidencias reales y muestra cuántas encontró. No borra tus reglas ni agrega sugerencias automáticamente: vos elegís cuáles incorporar. Sirve especialmente para reducir la categoría Otros.",
   "12. PAGO DE TARJETA\nMovimientos como PAGO DE TC, PAGO TC, PAGO TARJETA o PAGO DE TARJETA se pueden clasificar como ‘Pago de tarjeta’. eBROU normalmente no informa en ese movimiento qué compras componen el pago, por lo que la app no inventa un desglose. Como decidimos mantenerlo, Pago de tarjeta sigue contando como GASTO. Si además registraste individualmente las compras de esa tarjeta, puede existir doble conteo.",
   "13. LISTA NEGRA\nLa lista negra filtra notificaciones con palabras como rechazado, pendiente o recordatorio. No filtra movimientos reales del Excel. Las compras BROU fuertemente estructuradas y aprobadas están protegidas frente a falsos positivos genéricos.",
   "14. MOVIMIENTOS RECURRENTES\nPodés crear gastos o ingresos mensuales indicando un día del 1 al 31. Si el mes tiene menos días, se usa su último día válido. Si pasás varios meses sin abrir la app, recupera los meses recurrentes pendientes sin generar dos veces el mismo período.",
   "15. AGREGAR, EDITAR, ELIMINAR Y RECUPERAR\nAgregar permite cargar tipo, monto, moneda, descripción, categoría y fecha. En Inicio, tocá un movimiento para editarlo o mantenelo pulsado para eliminarlo. Si solo querés cambiar la categoría, tocá la línea ‘Categoría’ debajo de la descripción. Los movimientos eliminados pasan a la Papelera, desde donde se pueden restaurar mientras no la vacíes.",
   "16. GRÁFICOS Y DETALLE DE CATEGORÍAS\nGráficos permite analizar Categorías, Comercios, Evolución y Comparar períodos. En la pestaña Categorías, tocá cualquier categoría —por ejemplo Otros, Supermercado o Disco— para ver qué movimientos la integran. Dentro del detalle podés tocar un movimiento y cambiar su categoría; el cambio se refleja inmediatamente en el gráfico y también en la lista blanca cuando corresponde.",
   "17. PRESUPUESTO Y PROYECCIÓN\nPara cada categoría y mes se muestran gasto real, plan, mes anterior y mismo mes del año anterior. Podés usar esas referencias o escribir tu presupuesto. ‘Proyectar desde año anterior’ usa como base los gastos reales del año anterior.",
   "18. APARIENCIA Y SEGURIDAD\nEn Ajustes podés cambiar modo claro/oscuro, activar bloqueo biométrico, bloquear capturas de pantalla y la vista en aplicaciones recientes, y activar o desactivar la regla que pasa el salario de fin de mes al día 1 del mes siguiente.",
   "BUSCADOR DE LA AYUDA\nUsá el campo ‘🔍 Buscar en la ayuda…’ para encontrar rápidamente un tema. El buscador filtra secciones completas mientras escribís e ignora mayúsculas y acentos: por ejemplo, ‘credito’ encuentra ‘crédito’. Al borrar la búsqueda vuelve a aparecer toda la ayuda.",
   "SI FALTA UN MOVIMIENTO\nVerificá el acceso a notificaciones. Si sigue visible, usá ‘Leer notificaciones activas’. Revisá la lista negra. Si sigue faltando, importá el Excel de eBROU, que es la fuente más completa para reconstruir el movimiento.",
   "SI ALGO QUEDA EN ‘OTROS’\nPodés entrar en Gráficos → Categorías → Otros para ver todos los movimientos que están dentro. Tocá cualquiera para asignarle la categoría correcta. Ese cambio también ayuda a actualizar/aprender la lista blanca para movimientos similares. También podés usar ‘Sugerir según mi histórico’.",
   "PAPELERA Y DESHACER\nEn Ajustes → Papelera y deshacer podés restaurar movimientos eliminados. ‘Deshacer último cambio’ recupera el estado anterior de la última edición, cambio de categoría o eliminación. Si deshacés un cambio de categoría, también se recupera la lista blanca anterior. Vaciar la papelera elimina definitivamente esos elementos, por lo que esa acción pide confirmación.",
   "ENVIAR A LISTA NEGRA DESDE UN MOVIMIENTO\nAl editar un movimiento podés usar ‘⛔ Enviar a lista negra’. La app propone la descripción como regla, pero podés editarla antes de confirmar. Al aceptar, la palabra o frase se agrega a la lista negra para bloquear futuras notificaciones coincidentes y el movimiento actual se envía a la papelera, por lo que todavía puede restaurarse. La lista negra no filtra movimientos reales importados desde Excel eBROU.",
   "PRIVACIDAD\nLos movimientos, reglas y presupuestos se guardan localmente. Estas funciones no requieren las credenciales de tu banco."
  };
  LinearLayout root=form();EditText search=textEdit("🔍 Buscar en la ayuda…","");search.setSingleLine(true);root.addView(search,new LinearLayout.LayoutParams(-1,-2));ScrollView sc=new ScrollView(this);TextView t=tv("",15,TEXT);t.setPadding(dp(4),dp(10),dp(4),dp(18));sc.addView(t);root.addView(sc,new LinearLayout.LayoutParams(-1,dp(520)));
  Runnable render=()->{String q=helpNorm(search.getText().toString().trim());StringBuilder out=new StringBuilder();for(String sec:sections)if(q.isEmpty()||helpNorm(sec).contains(q)){if(out.length()>0)out.append("\n\n");out.append(sec);}t.setText(out.length()==0?"No encontré esa palabra en la ayuda. Probá con otro término.":out.toString());sc.post(()->sc.fullScroll(View.FOCUS_UP));};render.run();
  search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){render.run();}public void afterTextChanged(android.text.Editable e){}});
  new AlertDialog.Builder(this).setTitle("Ayuda · ControlGastos").setView(root).setPositiveButton("Entendido",null).show();
 }
 private boolean notificationEnabled(){String e=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");return e!=null&&e.contains(getPackageName());}private void openNotificationSettings(){try{startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"));}catch(Exception ignored){}}
}
